private static BigDecimal calcularJurosTabePrice(BigDecimal total, int parcelas) {
    BigDecimal um = BigDecimal.ONE;
    BigDecimal taxa = TAXA_JUROS_MENSAL;

    BigDecimal denominador = um.subtract(
        um.add(taxa).pow(parcelas).reciprocal()
    );

    BigDecimal parcela = total.multiply(taxa).divide(denominador, 10, RoundingMode.HALF_EVEN);
    BigDecimal totalFinal = parcela.multiply(new BigDecimal(parcelas));

    return totalFinal.subtract(total);
}

